struct WishState: Equatable {
    var title = ""
    var isSaving = false
    var savedID: Int?
    var error: String?
}
enum WishAction {
    case titleChanged(String), saveTapped, saved(Int), saveFailed
}
func reduce(_ state: WishState, _ action: WishAction) -> WishState {
    var next = state
    switch action {
    case let .titleChanged(value):
        if !state.isSaving {
            next.title = value
            next.savedID = nil
            next.error = nil
        }
    case .saveTapped:
        guard !state.title.isEmpty, !state.isSaving else { return state }
        next.isSaving = true
        next.error = nil
    case let .saved(id):
        next.isSaving = false
        next.savedID = id
    case .saveFailed:
        next.isSaving = false
        next.error = "Не сохранено"
    }
    return next
}
var state = WishState()
state = reduce(state, .titleChanged("Лампа"))
state = reduce(state, .saveTapped)
print(state.isSaving)
state = reduce(state, .saved(7))
print(state.savedID ?? -1)
print(state.isSaving)

