Внешняя запись удалена из вычисления. В рабочем сценарии эффект выполняет Store после принятого события; повторное вычисление reducer не повторяет запись.

struct WishOptions: Equatable { var isPinned = false }
enum OptionsAction { case togglePinned }
func optionsReduce(
    _ state: WishOptions, _ action: OptionsAction
) -> WishOptions {
    var next = state
    switch action { case .togglePinned: next.isPinned.toggle() }
    return next
}
final class OptionsStore {
    private(set) var state = WishOptions()
    func send(_ action: OptionsAction) { state = optionsReduce(state, action) }
}
let store = OptionsStore()
store.send(.togglePinned)
assert(store.state.isPinned)
store.send(.togglePinned)
assert(!store.state.isPinned)

Смена Bool стала событием и прошла через владельца state. Проверяется последовательность переключений, а не повтор сохранения title.

struct WishFilter: Equatable { var query = "" }
enum FilterAction { case queryChanged(String), reset }
func filterReduce(_ state: WishFilter, _ action: FilterAction) -> WishFilter {
    var next = state
    switch action {
    case let .queryChanged(value): next.query = value
    case .reset: next.query = ""
    }
    return next
}
final class FilterStore {
    private(set) var state = WishFilter()
    func send(_ action: FilterAction) { state = filterReduce(state, action) }
}
let store = FilterStore()
store.send(.queryChanged("Лампа"))
assert(store.state.query == "Лампа")
store.send(.reset)
assert(store.state.query.isEmpty)

Новый элемент восстановлен тем же маршрутом событий. Setter закрыт, а reset описывает самостоятельный переход к начальному полю.
